using System.Buffers.Binary;
using System.Text;

namespace FormatStudio.Runtime;

/// <summary>
/// Reads wire primitives from a <see cref="Stream"/> for code generated by Format Studio's <c>csharp-stream</c>
/// generator. Same primitives as <see cref="FormatReader"/>. When the length of the data is known (seekable streams,
/// slices, or the length passed to the constructor) counts are checked against the remaining bytes before anything is
/// allocated; otherwise against <see cref="MaxCount"/>.
/// </summary>
public sealed class FormatStreamReader
{
    private const int MaxNbtDepth = 512;

    private readonly Stream _stream;
    private readonly long _length;
    private readonly byte[] _scratch = new byte[16];
    private int _peeked = -1;
    private MemoryStream? _recording;

    /// <param name="length">The number of bytes to read, or -1 for all of a stream of unknown length (the default uses the
    /// rest of a seekable stream).</param>
    public FormatStreamReader(Stream stream, long? length = null)
    {
        _stream = stream;
        _length = length ?? (stream.CanSeek ? stream.Length - stream.Position : -1);
    }

    public FormatStreamReader(byte[] data) : this(new MemoryStream(data, writable: false), data.Length)
    {
    }

    /// <summary>The number of bytes read so far.</summary>
    public long Position { get; private set; }

    /// <summary>The number of bytes left, or -1 when the length is unknown.</summary>
    public long Remaining => _length < 0 ? -1 : _length - Position;

    /// <summary>The largest count accepted when the length of the data is unknown.</summary>
    public int MaxCount { get; set; } = 1 << 24;

    /// <summary>Whether all bytes have been read (for a stream of unknown length: whether it has ended).</summary>
    public bool AtEnd
    {
        get
        {
            if (_length >= 0) return Position >= _length;
            if (_peeked >= 0) return false;
            _peeked = _stream.ReadByte();
            return _peeked < 0;
        }
    }

    private FormatDataException Missing(long count) =>
        new($"Needs {count} bytes at offset {Position}, {(_length >= 0 ? $"{Remaining} remaining" : "the stream ended")}");

    private void Fill(Span<byte> target)
    {
        if (_length >= 0 && target.Length > _length - Position) throw Missing(target.Length);
        var offset = 0;
        if (target.Length > 0 && _peeked >= 0)
        {
            target[0] = (byte)_peeked;
            _peeked = -1;
            offset = 1;
        }

        while (offset < target.Length)
        {
            var read = _stream.Read(target[offset..]);
            if (read <= 0)
            {
                Position += offset;
                throw Missing(target.Length - offset);
            }

            offset += read;
        }

        Position += target.Length;
        _recording?.Write(target);
    }

    private ReadOnlySpan<byte> Fixed(int count)
    {
        var span = _scratch.AsSpan(0, count);
        Fill(span);
        return span;
    }

    private byte[] Take(int count)
    {
        if (count < 0) throw new FormatDataException($"Negative length {count} at offset {Position}");
        if (_length >= 0 && count > _length - Position) throw Missing(count);
        var bytes = new byte[count];
        Fill(bytes);
        return bytes;
    }

    /// <summary>Reads <paramref name="length"/> bytes as a separate reader (a length-delimited section).</summary>
    public FormatStreamReader Slice(int length) => new(Take(length));

    /// <summary>Validates a collection count read from the wire before anything is allocated.</summary>
    public int CheckCount(long count, int minElementSize, int max = int.MaxValue)
    {
        if (count < 0) throw new FormatDataException($"Negative count {count} at offset {Position}");
        if (count > max) throw new FormatDataException($"Count {count} exceeds the maximum of {max} at offset {Position}");
        if (_length >= 0)
        {
            if (minElementSize > 0 && count > Remaining / minElementSize)
                throw new FormatDataException($"Count {count} needs at least {count * minElementSize} bytes at offset {Position}, {Remaining} remaining");
        }
        else if (count > MaxCount)
        {
            throw new FormatDataException($"Count {count} exceeds the limit of {MaxCount} for data of unknown length at offset {Position}");
        }

        return (int)Math.Min(count, int.MaxValue);
    }

    public int CheckCount(ulong count, int minElementSize, int max = int.MaxValue) =>
        CheckCount(count > long.MaxValue ? long.MaxValue : (long)count, minElementSize, max);

    public bool ReadBool() => ReadU8() != 0;
    public byte ReadU8() => Fixed(1)[0];
    public sbyte ReadI8() => (sbyte)ReadU8();

    public ushort ReadU16LE() => BinaryPrimitives.ReadUInt16LittleEndian(Fixed(2));
    public ushort ReadU16BE() => BinaryPrimitives.ReadUInt16BigEndian(Fixed(2));
    public short ReadI16LE() => BinaryPrimitives.ReadInt16LittleEndian(Fixed(2));
    public short ReadI16BE() => BinaryPrimitives.ReadInt16BigEndian(Fixed(2));
    public uint ReadU32LE() => BinaryPrimitives.ReadUInt32LittleEndian(Fixed(4));
    public uint ReadU32BE() => BinaryPrimitives.ReadUInt32BigEndian(Fixed(4));
    public int ReadI32LE() => BinaryPrimitives.ReadInt32LittleEndian(Fixed(4));
    public int ReadI32BE() => BinaryPrimitives.ReadInt32BigEndian(Fixed(4));
    public ulong ReadU64LE() => BinaryPrimitives.ReadUInt64LittleEndian(Fixed(8));
    public ulong ReadU64BE() => BinaryPrimitives.ReadUInt64BigEndian(Fixed(8));
    public long ReadI64LE() => BinaryPrimitives.ReadInt64LittleEndian(Fixed(8));
    public long ReadI64BE() => BinaryPrimitives.ReadInt64BigEndian(Fixed(8));
    public Half ReadF16LE() => BinaryPrimitives.ReadHalfLittleEndian(Fixed(2));
    public Half ReadF16BE() => BinaryPrimitives.ReadHalfBigEndian(Fixed(2));
    public float ReadF32LE() => BinaryPrimitives.ReadSingleLittleEndian(Fixed(4));
    public float ReadF32BE() => BinaryPrimitives.ReadSingleBigEndian(Fixed(4));
    public double ReadF64LE() => BinaryPrimitives.ReadDoubleLittleEndian(Fixed(8));
    public double ReadF64BE() => BinaryPrimitives.ReadDoubleBigEndian(Fixed(8));

    public uint ReadVarUInt32()
    {
        uint result = 0;
        for (var shift = 0; shift < 35; shift += 7)
        {
            var b = ReadU8();
            result |= (uint)(b & 0x7F) << shift;
            if ((b & 0x80) == 0)
            {
                if (shift == 28 && b > 0x0F) throw new FormatDataException($"VarUInt32 overflow at offset {Position - 1}");
                return result;
            }
        }

        throw new FormatDataException($"VarUInt32 longer than 5 bytes at offset {Position}");
    }

    public ulong ReadVarUInt64()
    {
        ulong result = 0;
        for (var shift = 0; shift < 70; shift += 7)
        {
            var b = ReadU8();
            result |= (ulong)(b & 0x7F) << shift;
            if ((b & 0x80) == 0)
            {
                if (shift == 63 && b > 0x01) throw new FormatDataException($"VarUInt64 overflow at offset {Position - 1}");
                return result;
            }
        }

        throw new FormatDataException($"VarUInt64 longer than 10 bytes at offset {Position}");
    }

    /// <summary>Two's complement LEB128 (Java VarInt).</summary>
    public int ReadVarInt32() => (int)ReadVarUInt32();

    public long ReadVarInt64() => (long)ReadVarUInt64();

    /// <summary>Zigzag LEB128 (e.g. the Bedrock "varint").</summary>
    public int ReadZigZag32()
    {
        var value = ReadVarUInt32();
        return (int)(value >> 1) ^ -(int)(value & 1);
    }

    public long ReadZigZag64()
    {
        var value = ReadVarUInt64();
        return (long)(value >> 1) ^ -(long)(value & 1);
    }

    /// <summary>A UUID as two little-endian 64-bit halves, most significant half first.</summary>
    public Guid ReadUuidLE()
    {
        var bytes = Fixed(16);
        Span<byte> big = stackalloc byte[16];
        BinaryPrimitives.WriteUInt64BigEndian(big, BinaryPrimitives.ReadUInt64LittleEndian(bytes));
        BinaryPrimitives.WriteUInt64BigEndian(big[8..], BinaryPrimitives.ReadUInt64LittleEndian(bytes[8..]));
        return new Guid(big, bigEndian: true);
    }

    /// <summary>A UUID in RFC 4122 byte order (two big-endian 64-bit halves).</summary>
    public Guid ReadUuidBE() => new(Fixed(16), bigEndian: true);

    public string ReadUtf8(int byteCount) => Encoding.UTF8.GetString(Take(byteCount));

    /// <summary>A UTF-8 string in a field of <paramref name="byteCount"/> bytes, without the trailing <paramref name="pad"/> bytes.</summary>
    public string ReadUtf8Padded(int byteCount, byte pad) => Encoding.UTF8.GetString(((ReadOnlySpan<byte>)Take(byteCount)).TrimEnd(pad));

    /// <summary>A UTF-8 string in a field of <paramref name="byteCount"/> bytes that ends at the first zero byte, or with the field.</summary>
    public string ReadUtf8Terminated(int byteCount)
    {
        ReadOnlySpan<byte> bytes = Take(byteCount);
        var end = bytes.IndexOf((byte)0);
        return Encoding.UTF8.GetString(end < 0 ? bytes : bytes[..end]);
    }

    public string ReadUtf8Zero()
    {
        var bytes = new MemoryStream();
        while (true)
        {
            if (_length >= 0 && Position >= _length) throw new FormatDataException($"Missing string terminator after offset {Position}");
            var b = ReadU8();
            if (b == 0) break;
            bytes.WriteByte(b);
        }

        return Encoding.UTF8.GetString(bytes.GetBuffer(), 0, (int)bytes.Length);
    }

    /// <summary>The rest of the data as UTF-8.</summary>
    public string ReadUtf8ToEnd() => Encoding.UTF8.GetString(ReadToEnd());

    public byte[] ReadBytes(int count) => Take(count);

    /// <summary>The rest of the data.</summary>
    public byte[] ReadToEnd()
    {
        if (_length >= 0) return Take((int)Math.Min(Remaining, int.MaxValue));
        var bytes = new MemoryStream();
        if (_peeked >= 0)
        {
            bytes.WriteByte((byte)_peeked);
            _peeked = -1;
        }

        _stream.CopyTo(bytes);
        Position += bytes.Length;
        var result = bytes.ToArray();
        _recording?.Write(result);
        return result;
    }

    /// <summary>Reads one NBT tag (big endian, named root) and returns its raw bytes.</summary>
    public byte[] ReadNbtJava() => ReadNbt(NbtLayout.Java, named: true);

    /// <summary>Reads one NBT tag (big endian, unnamed root) and returns its raw bytes.</summary>
    public byte[] ReadNbtJavaNetwork() => ReadNbt(NbtLayout.Java, named: false);

    /// <summary>Reads one NBT tag (little endian, named root) and returns its raw bytes.</summary>
    public byte[] ReadNbtBedrock() => ReadNbt(NbtLayout.Bedrock, named: true);

    /// <summary>Reads one NBT tag (little endian with varints, named root) and returns its raw bytes.</summary>
    public byte[] ReadNbtBedrockNetwork() => ReadNbt(NbtLayout.BedrockNetwork, named: true);

    private enum NbtLayout
    {
        Java,
        Bedrock,
        BedrockNetwork,
    }

    private byte[] ReadNbt(NbtLayout layout, bool named)
    {
        _recording = new MemoryStream();
        try
        {
            var type = ReadU8();
            if (type != 0)
            {
                if (named) SkipNbtString(layout);
                SkipNbtPayload(layout, type, 0);
            }

            return _recording.ToArray();
        }
        finally
        {
            _recording = null;
        }
    }

    private void Skip(int count)
    {
        Span<byte> buffer = stackalloc byte[256];
        while (count > 0)
        {
            var chunk = Math.Min(count, buffer.Length);
            Fill(buffer[..chunk]);
            count -= chunk;
        }
    }

    private void SkipNbtString(NbtLayout layout) => Skip(layout switch
    {
        NbtLayout.Java => ReadU16BE(),
        NbtLayout.Bedrock => ReadU16LE(),
        _ => CheckCount(ReadVarUInt32(), 1),
    });

    private int ReadNbtLength(NbtLayout layout, int elementSize) => CheckCount(layout switch
    {
        NbtLayout.Java => ReadI32BE(),
        NbtLayout.Bedrock => ReadI32LE(),
        _ => ReadZigZag32(),
    }, elementSize);

    private void SkipNbtPayload(NbtLayout layout, byte type, int depth)
    {
        if (depth > MaxNbtDepth) throw new FormatDataException("NBT nested too deeply");
        var network = layout == NbtLayout.BedrockNetwork;
        switch (type)
        {
            case 1: Skip(1); break;
            case 2: Skip(2); break;
            case 3: if (network) ReadZigZag32(); else Skip(4); break;
            case 4: if (network) ReadZigZag64(); else Skip(8); break;
            case 5: Skip(4); break;
            case 6: Skip(8); break;
            case 7: Skip(ReadNbtLength(layout, 1)); break;
            case 8: SkipNbtString(layout); break;
            case 9:
                var elementType = ReadU8();
                var count = ReadNbtLength(layout, 0);
                for (var i = 0; i < count; i++) SkipNbtPayload(layout, elementType, depth + 1);
                break;
            case 10:
                while (true)
                {
                    var childType = ReadU8();
                    if (childType == 0) break;
                    SkipNbtString(layout);
                    SkipNbtPayload(layout, childType, depth + 1);
                }

                break;
            case 11:
                var ints = ReadNbtLength(layout, network ? 1 : 4);
                for (var i = 0; i < ints; i++) SkipNbtPayload(layout, 3, depth + 1);
                break;
            case 12:
                var longs = ReadNbtLength(layout, network ? 1 : 8);
                for (var i = 0; i < longs; i++) SkipNbtPayload(layout, 4, depth + 1);
                break;
            default:
                throw new FormatDataException($"Unknown NBT tag type {type} at offset {Position - 1}");
        }
    }
}
